mapper.select:
SELECT ri.created_at AS createdAt, u.name AS userName, ri.action_type AS actionType, ri.channel AS channel, ri.is_control AS isControl, ri.risk_type AS riskType, CASE WHEN ri.is_control THEN 'CONTROL' WHEN io.converted THEN 'CONVERTED' ELSE 'NO_RESPONSE' END AS outcome FROM retention_intervention ri JOIN users u ON u.user_id = ri.user_id LEFT JOIN intervention_outcome io ON io.intervention_id = ri.intervention_id
WHERE ri.risk_type = #{riskType}
ORDER BY ri.created_at DESC LIMIT #{limit}
